function mobileSchedule(entries){const days=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'],today=new Date().getDay()||7;return '<div class="schedule-mobile">'+days.map((day,i)=>{const classes=entries.filter(e=>e.day===i+1).sort((a,b)=>a.start.localeCompare(b.start));if(!classes.length)return '';return '<section class="schedule-mobile-day"><h3>'+day+(today===i+1?' <span>Hoy</span>':'')+'</h3>'+classes.map(e=>'<button class="schedule-mobile-entry schedule-color-'+esc(e.color)+'" data-schedule-mobile="'+esc(e.id)+'"><span class="schedule-mobile-time">'+esc(e.start)+'–'+esc(e.end)+'</span><span><b class="group-tag">'+esc(e.group||'Clase')+'</b><strong>'+esc(e.subject)+'</strong><small>'+esc(e.room||'Sin aula indicada')+'</small></span></button>').join('')+'</section>'}).join('')+'</div>'}
function scheduleMinutes(value){const [h,m]=value.split(':').map(Number);return h*60+m}
function scheduleDashboard(){const entries=scheduleEntries(),days=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'],lastDay=Math.max(5,...entries.map(e=>e.day)),today=new Date().getDay()||7,starts=[...new Set(entries.map(e=>e.start))].sort();return `<div class="card compact"><h2>Mi horario semanal</h2><div class="schedule-toolbar"><p class="muted">Semana completa · Pulsa una clase para editarla.</p><button class="primary" id="addScheduleEntry">+ Agregar clase</button></div><div class="schedule-compact-wrap"><div class="schedule-compact" style="--schedule-days:${lastDay}" role="table" aria-label="Horario semanal"><div class="schedule-compact-head" role="columnheader">Hora</div>${days.slice(0,lastDay).map((day,i)=>`<div class="schedule-compact-head ${today===i+1?'schedule-today':''}" role="columnheader">${day}${today===i+1?'<span>Hoy</span>':''}</div>`).join('')}${starts.map(start=>`<div class="schedule-compact-time" role="rowheader">${esc(start)}</div>${days.slice(0,lastDay).map((day,i)=>`<div class="schedule-compact-cell" role="cell">${entries.filter(e=>e.day===i+1&&e.start===start).map(e=>`<button class="schedule-compact-class schedule-color-${e.color}" data-schedule-edit="${e.id}" title="${esc(e.subject)} · ${esc(e.group)} · ${esc(e.room)} · ${esc(e.start)}–${esc(e.end)}"><span class="schedule-compact-top"><b>${esc(e.group||'Clase')}</b><span>${esc(e.start)}–${esc(e.end)}</span></span><strong>${esc(e.subject)}</strong>${e.room?`<span class="schedule-compact-room">${esc(e.room)}</span>`:''}</button>`).join('')}</div>`).join('')}`).join('')}</div></div>${mobileSchedule(entries)}${!entries.length?'<p class="empty">Agrega tu primera clase para organizar la semana.</p>':''}<p class="schedule-hint">${entries.length} clases · Horas en formato de 24 horas · Se omiten las franjas sin clases.</p></div>`}

function bindSchedule(){bindAll('[data-schedule-mobile]',b=>scheduleEntryForm(b.dataset.scheduleMobile));if($('addScheduleEntry'))$('addScheduleEntry').onclick=()=>scheduleEntryForm();bindAll('[data-schedule-edit]',b=>scheduleEntryForm(b.dataset.scheduleEdit))}
function scheduleEntryForm(editId=null){const existing=(scheduleEntries()).find(e=>e.id===editId),days=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'],colors=[['blue','Azul'],['violet','Violeta'],['teal','Turquesa'],['green','Verde'],['amber','Amarillo'],['orange','Naranja'],['slate','Gris azulado']];dialog(existing?'Editar clase del horario':'Agregar clase al horario',`<p class="muted">Puedes escribir libremente los nombres. Cambiar este bloque solo modifica tu horario personal.</p><label for="scheduleSubject">Materia / nombre de la clase</label><input id="scheduleSubject" required maxlength="200" list="scheduleSubjects" value="${esc(existing?.subject||'')}"><datalist id="scheduleSubjects">${subjects().map(s=>`<option value="${esc(s.name)}"></option>`).join('')}</datalist><div class="columns"><div><label for="scheduleGroup">Grupo o grupos</label><input id="scheduleGroup" maxlength="150" list="scheduleGroups" placeholder="Por ejemplo, LEX-1A" value="${esc(existing?.group||'')}"><datalist id="scheduleGroups">${list('groups').map(g=>`<option value="${esc(g.name)}"></option>`).join('')}</datalist></div><div><label for="scheduleRoom">Aula / laboratorio</label><input id="scheduleRoom" maxlength="150" value="${esc(existing?.room||'')}" placeholder="Por ejemplo, Lab - 01"></div></div><div class="columns"><div><label for="scheduleDay">Día</label><select id="scheduleDay">${options(days.map((name,i)=>({id:String(i+1),name})),String(existing?.day||1))}</select></div><div><label for="scheduleColor">Color</label><select id="scheduleColor">${options(colors.map(([id,name])=>({id,name})),existing?.color||'blue')}</select></div></div><div class="columns"><div><label for="scheduleStart">Hora de inicio</label><input type="time" id="scheduleStart" required value="${esc(existing?.start||'07:00')}"></div><div><label for="scheduleEnd">Hora de fin</label><input type="time" id="scheduleEnd" required value="${esc(existing?.end||'08:40')}"></div></div><p class="muted">Ejemplo: 13:00 equivale a la 1 de la tarde. Si una materia se imparte en varios días, agrega un bloque para cada día.</p>${existing?'<button type="button" class="danger" id="deleteScheduleEntry">Eliminar esta clase</button>':''}`,async()=>{const entry={id:existing?.id||Aula.id(),subject:$('scheduleSubject').value.trim(),group:$('scheduleGroup').value.trim(),room:$('scheduleRoom').value.trim(),day:Number($('scheduleDay').value),start:$('scheduleStart').value,end:$('scheduleEnd').value,color:$('scheduleColor').value};if(!entry.subject)throw Error('Escribe el nombre de la materia.');if(!entry.start||!entry.end||entry.end<=entry.start)throw Error('La hora de fin debe ser posterior a la hora de inicio.');if((scheduleEntries()).some(e=>e.id!==entry.id&&e.day===entry.day&&entry.start<e.end&&entry.end>e.start))throw Error('Ya hay otra clase en ese horario. Ajusta el día o las horas para evitar que se encimen.');await mutate(d=>{const schedule=semesterSchedule(d);const i=schedule.findIndex(e=>e.id===entry.id);if(i>=0)schedule[i]=entry;else schedule.push(entry)});render()});if(existing)$('deleteScheduleEntry').onclick=async()=>{if(!confirm('¿Eliminar esta clase de tu horario?'))return;try{await mutate(d=>{d.semesters.find(s=>s.id===d.activeSemesterId).personalSchedule=semesterSchedule(d).filter(e=>e.id!==editId)});closeModal();render()}catch(error){modalError(error.message)}}}

function groupAbove(name){return name?'<div class="group-above">'+groupTag(name)+'</div>':''}
function groupTag(name){return name?'<span class="group-tag">'+esc(name)+'</span>':'—'}
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db=null,view='home',subject='',group='',period='',activity='',student='',draft=null,draftBaseline='',reviewFilter='',reviewFilterActivity='',criterionIndex=0,ix=null,profileId=null,saveQueue=Promise.resolve(),modalCleanup=null;
const fmt=x=>x===null||x===undefined?'—':String(x),nowDate=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},ev=()=>db.subjects.find(x=>x.id===subject)?.evaluation||Aula.evaluation();
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function toast(message){if($('modal').open){modalError(message);return}$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
function modalError(message){$('modalError').textContent=message;$('modalError').hidden=false;$('modalError').focus({preventScroll:true})}
