function closeModal(){if(modalCleanup){const cleanup=modalCleanup;modalCleanup=null;cleanup()}$('modal').close();$('modalForm').onsubmit=null}
function dialog(title,html,submit,saveLabel='Guardar'){if(modalCleanup){const cleanup=modalCleanup;modalCleanup=null;cleanup()}clearError();$('modalGroupBadge').hidden=true;$('modalGroupBadge').textContent='';$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modalContent').scrollTop=0;$('modalSave').textContent=saveLabel;$('modalSave').classList.toggle('danger',/eliminar/i.test(saveLabel));$('modalSave').classList.toggle('save-action',/guardar|aplicar|confirmar/i.test(saveLabel));$('modalSave').hidden=!submit;$('modalForm').onsubmit=async e=>{e.preventDefault();if($('modalSave').disabled)return;clearError();$('modalSave').disabled=true;try{if(submit&&await submit()!==false)closeModal()}catch(error){modalError(error.message)}finally{$('modalSave').disabled=false}};$('modal').showModal()}
function help(title,text){return `<details class="help"><summary>? ${esc(title)}</summary><p>${esc(text)}</p></details>`}
function options(items,value,blank=null){return (blank!==null?`<option value="">${esc(blank)}</option>`:'')+items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}
function select(value,items){return items.some(x=>x.id===value)?value:items[0]?.id||''}
function list(k){const rows=Aula.visible(db,k);return k==='activities'?rows.sort((a,b)=>String(a.code||a.name).localeCompare(String(b.code||b.name),'es',{numeric:true,sensitivity:'base'})||a.name.localeCompare(b.name,'es',{numeric:true,sensitivity:'base'})):rows}
function subjects(){return list('subjects').filter(s=>s.semesterId===db.activeSemesterId)}
function subjectChoices(){const rows=subjects();return rows.map((s,i)=>({...s,name:rows.filter(x=>Aula.norm(x.name)===Aula.norm(s.name)).length>1?s.name+' · '+(groupsForSubject(s.id).map(g=>g.name).join(', ')||'registro '+(i+1)):s.name}))}
function groupsForSubject(sid){return list('groups').filter(g=>g.subjectId===sid)}
function groups(){return list('groups').filter(g=>g.subjectId===subject)}
function periods(){return list('periods').filter(p=>p.subjectId===subject)}
function activities(){return list('activities').filter(a=>a.groupId===group&&a.periodId===period)}
function inCurrentRoster(s){const g=db.groups.find(g=>g.id===s.groupId),key=Aula.idKey(s.number,db.settings.idMatching);return s.enrollmentStatus!=='baja'&&!s.participationInactive&&!s.rosterMissing&&!g?.excludedRosterIDs?.includes(key)&&(!g?.listaRosterIDs||g.listaRosterIDs.includes(key))}
function roster(groupId=group){return list('students').filter(s=>s.groupId===groupId&&inCurrentRoster(s)).sort(compareStudents)}
function act(){return db.activities.find(a=>a.id===activity)}
function matchesStudentSearch(s,q){const key=Aula.idKey(q,db.settings.idMatching);return Aula.norm([s.name,s.number,s.originalNumber||'',s.moodleIdentity?.number||''].join(' ')).includes(q)||!!key&&Aula.idKey(s.number,db.settings.idMatching).includes(key)}
function studentNameParts(s){const comma=s.name.includes(',')?s.name.split(','):null;return {given:s.givenName||s.moodleIdentity?.firstName||comma?.slice(1).join(',').trim()||s.name,family:s.familyName||s.moodleIdentity?.lastName||comma?.[0]?.trim()||''}}
function compareStudents(a,b){const x=studentNameParts(a),y=studentNameParts(b),family=db.settings.studentSort==='surname';return (family?x.family||a.name:x.given).localeCompare(family?y.family||b.name:y.given,'es',{sensitivity:'base',numeric:true})||x.given.localeCompare(y.given,'es',{sensitivity:'base',numeric:true})||a.number.localeCompare(b.number,'es',{numeric:true})}
function studentSearchControl(id){return `<div class="student-filter-field student-search-field"><label for="${id}">Buscar alumno</label><div class="student-search-input"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input id="${id}" type="search" placeholder="Nombre, apellidos o ID" autocomplete="off"></div></div>`}
function studentSortControl(id){return `<div class="student-filter-field student-sort-field"><label for="${id}">Ordenar alumnos por</label><select id="${id}"><option value="name" ${db.settings.studentSort!=='surname'?'selected':''}>Nombre</option><option value="surname" ${db.settings.studentSort==='surname'?'selected':''}>Apellidos</option></select></div>${db.settings.studentSort==='surname'&&roster().some(s=>!studentNameParts(s).family)?'<small class="muted">Para alumnos sin apellidos separados, reimporta Lista/CASISTENCIA. Se conservan sus calificaciones.</small>':''}`}
