function ctx(){subject=select(subject,subjects());group=select(group,groups());period=select(period,periods());activity=select(activity,activities());student=select(student,roster());ix=Aula.index(db)}
function dirty(){return !!draft&&JSON.stringify(draft)!==draftBaseline}
function leave(){if($('saveStatus').textContent==='Guardando…'){toast('Espera a que termine el guardado.');return false}if(dirty()&&!confirm('Hay una revisión sin guardar. ¿Descartar los cambios?'))return false;draft=null;draftBaseline='';return true}
function navigate(next){if(!leave())return;view=next;profileId=null;render()}
async function mutate(change,message='Guardado'){const task=saveQueue.then(async()=>{const next=Aula.clone(db);await change(next);Aula.applyIdFormat(next);Aula.validate(next);$('saveStatus').textContent='Guardando…';try{const result=await AulaStorage.write(next,db.revision);db=result;ix=Aula.index(db);$('saveStatus').textContent='Guardado · '+AulaStorage.mode;return true}catch(e){$('saveStatus').textContent='No guardado';throw e}});saveQueue=task.catch(()=>{});await task;if(message&&!$('modal').open)toast(message);return true}
function bindAll(selector,handler){document.querySelectorAll(selector).forEach(b=>b.onclick=()=>handler(b))}
function button(label,action,primary=false){return `<button ${primary?'class="primary"':''} data-action="${action}">${esc(label)}</button>`}
function stateBadge(cell){if(!cell.submission.id&&!cell.review)return '<span class="state state-pending">Sin registro de Moodle</span>';return `<span class="state state-${esc(cell.status)}" title="${esc(cell.definition.name)}">${esc(cell.definition.name)}</span>`}
function scaleScore(percent,evaluation=ev()){return fmt(Aula.displayScore(percent,evaluation))}
function openReview(aid,sid){if(!leave())return;const a=db.activities.find(x=>x.id===aid),s=db.students.find(x=>x.id===sid);if(!a||!s||a.trashId||s.trashId){toast('Esta actividad o alumno no está disponible.');return}db.activeSemesterId=Aula.semesterOf(db,a.subjectId);subject=a.subjectId;group=a.groupId;period=a.periodId;activity=aid;student=sid;view='review';profileId=null;render()}
function initPageSections(){if(['home','review'].includes(view))return;const used=new Set();document.querySelectorAll('#content .card h2').forEach((heading,i)=>{if(heading.querySelector('.section-toggle'))return;const card=heading.closest('.card');if(!card||used.has(card))return;used.add(card);const title=heading.textContent.trim(),key=view+'-'+Aula.norm(title).replace(/[^a-z0-9]+/g,'-').replace(/-\d+.*$/,''),id='page-section-'+view+'-'+i;let closed=false;try{closed=localStorage.getItem('profeflow-section-'+key)==='closed'}catch{}card.classList.toggle('collapsible-card',true);let header=heading;while(header.parentElement&&header.parentElement!==card)header=header.parentElement;header.setAttribute('data-collapse-header','true');card.classList.toggle('section-minimized',closed);heading.innerHTML+=' <button type="button" class="section-toggle" id="'+id+'" aria-expanded="'+!closed+'">'+(closed?'Mostrar':'Minimizar')+' <span aria-hidden="true">'+(closed?'＋':'−')+'</span></button>';const button=$(id);button.onclick=()=>{closed=!closed;card.classList.toggle('section-minimized',closed);button.setAttribute('aria-expanded',String(!closed));button.innerHTML=(closed?'Mostrar':'Minimizar')+' <span aria-hidden="true">'+(closed?'＋':'−')+'</span>';try{localStorage.setItem('profeflow-section-'+key,closed?'closed':'open')}catch{}}})}
