function otherPeriodActivitiesNotice(){const all=list('activities').filter(a=>a.groupId===group&&a.periodId!==period);if(!all.length)return 'Todavía no hay actividades. Crea la primera desde el botón Crear actividad.';return 'No hay actividades en el parcial seleccionado. En otros parciales de este grupo tienes '+all.length+' actividades.<div class="chips">'+periods().filter(p=>all.some(a=>a.periodId===p.id)).map(p=>'<button type="button" data-other-period="'+p.id+'">Ver '+esc(p.name)+' · '+all.filter(a=>a.periodId===p.id).length+' actividades</button>').join('')+'</div>'}
function render(){ctx();rememberContext();const names={planning:'Horario y calendario',admin:'Administración',home:'Inicio',examGroups:'Exámenes por turnos',attendance:'Asistencia',activityAttendance:'Actividades y asistencia',participation:'Participación y posibles bajas',eligibility:'Derecho a examen final',grades:'Libro de calificaciones',review:'Revisión',activities:'Actividades y plantillas',students:'Alumnos',manage:'Organización',data:'Datos y respaldos',justifications:'Justificantes'};$('title').textContent=names[view];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('semesterSelect').innerHTML=options(db.semesters.filter(x=>!x.trashId),db.activeSemesterId);$('filters').hidden=['home','planning','admin','data','justifications','eligibility'].includes(view);$('filters').classList.toggle('review-mode',view==='review');$('filters').innerHTML=[['Materia','subject',subjectChoices(),subject],['Grupo','group',groups(),group],['Parcial','period',periods(),period],['Actividad','activity',activities(),activity]].map(([label,id,items,value])=>`<div ${id==='activity'&&view!=='review'||id==='period'&&['attendance','participation','examGroups'].includes(view)?'hidden':''}><label for="${id}">${label}</label><select id="${id}">${options(items,value,items.length?null:'Sin registros')}</select></div>`).join('');['subject','group','period','activity'].forEach(key=>$(key).onchange=e=>{if(!leave()){render();return}if(key==='subject')subject=e.target.value;if(key==='group')group=e.target.value;if(key==='period')period=e.target.value;if(key==='activity')activity=e.target.value;profileId=null;render()});({planning:renderPlanning,admin:renderAdmin,home:renderHome,examGroups:renderExamGroups,attendance:renderAttendance,activityAttendance:renderActivityAttendance,participation:renderParticipation,eligibility:renderEligibility,grades:renderGrades,review:renderReview,activities:renderActivities,students:renderStudents,manage:renderManage,data:renderData,justifications:renderJustifications})[view]();bindGlobalActions();bindAll('[data-plan-open]',()=>navigate('planning'));bindAll('[data-other-period]',b=>{period=b.dataset.otherPeriod;render()});initPageSections();renderSectionNavigation()}
function bindGlobalActions(){bindAll('[data-empty-import]',b=>rosterImport(b.dataset.emptyImport));bindAll('[data-empty-students]',b=>{if(!leave())return;const g=db.groups.find(g=>g.id===b.dataset.emptyStudents);if(!g)return;subject=g.subjectId;group=g.id;view='students';profileId=null;render();$('showInactiveStudents').checked=true;$('showInactiveStudents').onchange()});bindAll('[data-open-review]',b=>openReview(b.dataset.openReview,b.dataset.student));bindAll('[data-profile]',b=>{if(!leave())return;profileId=b.dataset.profile;view='students';const s=db.students.find(x=>x.id===profileId),g=db.groups.find(x=>x.id===s?.groupId);if(g){subject=g.subjectId;group=g.id;db.activeSemesterId=Aula.semesterOf(db,subject)}render()});bindAll('[data-action]',b=>({subject:()=>entityForm('subjects'),group:()=>entityForm('groups'),period:()=>entityForm('periods'),student:()=>entityForm('students'),roster:rosterImport,activity:()=>activityForm(),template:()=>templateForm(),evaluation:evaluationForm,semester:semesterForm,settings:settingsForm,gradesImport:gradeImport,export:exportDialog,continue:continueReview,justifications:()=>navigate('justifications'),newJustification:()=>justificationForm()})[b.dataset.action]?.())}
function dashboardEmptyGroups(){const activeSubjects=new Set(subjects().map(s=>s.id));return list('groups').filter(g=>activeSubjects.has(g.subjectId)&&roster(g.id).length===0).sort((a,b)=>{const name=g=>(db.subjects.find(s=>s.id===g.subjectId)?.name||'')+' '+g.name;return name(a).localeCompare(name(b),'es',{numeric:true,sensitivity:'base'})})}
function emptyGroupsDashboard(){const empty=dashboardEmptyGroups();if(!empty.length)return '';return `<div class="card compact" id="emptyGroupsDashboard"><h2>Grupos sin alumnos · ${empty.length}</h2><p class="muted">Grupos del semestre actual sin alumnos activos para revisar.</p><div class="table-scroll"><table><thead><tr><th>Materia</th><th>Situación</th><th>Acciones</th></tr></thead><tbody>${empty.map(g=>{const existing=db.students.filter(s=>s.groupId===g.id&&!s.trashId).length;return `<tr><td>${groupAbove(g.name)}${esc(db.subjects.find(s=>s.id===g.subjectId)?.name||'')}</td><td>${existing?'Sin alumnos activos · '+existing+' registros de bajas, archivados o fuera del padrón':'Sin lista de alumnos'}</td><td><button data-empty-import="${g.id}">Importar lista</button>${existing?`<button data-empty-students="${g.id}">Ver registros</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`}
function dashboardAttendanceLists(today=nowDate()){
 const active=new Set(subjects().map(s=>s.id)),monday=new Date(today+'T00:00:00Z');monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7);const start=monday.toISOString().slice(0,10);
 return list('groups').filter(g=>active.has(g.subjectId)).map(g=>{const sessions=g.attendanceSessions||[],manual=db.students.filter(s=>s.groupId===g.id&&!s.trashId&&s.enrollmentStatus!=='baja').flatMap(s=>(s.attendance||[]).filter(m=>m.source==='manual')),source=g.attendanceSnapshot,snap=source||sessions.length?{importedAt:source?.importedAt||'',dates:[...new Set([...(source?.dates||[]),...sessions.map(s=>s.date)])],students:{...(source?.students||{}),manual:[...manual,...sessions.filter(s=>s.cancelled).map(s=>({date:s.date,state:'cancelled'}))]}}:null;let status='unknown',message='Sin lista para comprobar. Sube la descarga de la plataforma.',last='';
 if(snap){const marks=Object.values(snap.students||{}).flat(),dates=[...new Set(snap.dates)],elapsed=dates.filter(d=>d>=start&&d<=today),blank=elapsed.filter(d=>!marks.some(m=>m.date===d));last=marks.map(m=>m.date).filter(d=>d<=today).sort().at(-1)||'';
 if(blank.length){status='stale';message='Faltan marcas del grupo en: '+blank.join(', ')+'. Revisa si necesitas actualizar la lista.'}
 else if(elapsed.length){status='current';message='Hay marcas del grupo en los días transcurridos de esta semana.'}
 else message='La hoja no tiene fechas de clase transcurridas de esta semana. No se puede comprobar su actualización.';
 }return {group:g,status,message,last,importedAt:snap?.importedAt||''}})
}
function attendanceListsDashboard(){const rows=dashboardAttendanceLists(),pending=rows.filter(r=>r.status!=='current').length;if(!rows.length)return '';const displayDate=value=>new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));return `<section class="card compact attendance-dashboard-panel" id="attendanceListsDashboard" aria-label="Actualización de listas"><div class="attendance-panel-heading"><div><h2>Actualización de listas</h2><p class="muted">Asistencia · Esta semana por grupo</p></div><span class="attendance-count">${pending?pending+' por comprobar':'Todo al día'}</span></div><div class="attendance-list">${rows.map(r=>`<article class="attendance-item"><div class="attendance-course">${groupTag(r.group.name)}<h3>${esc(db.subjects.find(s=>s.id===r.group.subjectId)?.name||'')}</h3></div><div class="attendance-status"><span class="attendance-badge attendance-badge-${r.status}"><span aria-hidden="true">${r.status==='current'?'✓':r.status==='stale'?'!':'?'}</span>${r.status==='current'?'Con registros esta semana':r.status==='stale'?'Revisar actualización':'Sin comprobar'}</span><p>${esc(r.message)}</p></div><div class="attendance-dates"><span>Última fecha con marcas</span><strong>${r.last?esc(displayDate(r.last)):'Sin marcas'}</strong><p>${r.importedAt?'Importada el '+esc(new Date(r.importedAt).toLocaleString('es-MX',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})):r.last?'Registro directo en ProfeFlow':'Aún no se ha importado'}</p></div><button class="attendance-update" data-attendance-update="${r.group.id}">Actualizar lista <span aria-hidden="true">↗</span></button></article>`).join('')}</div><details class="attendance-help"><summary>¿Cómo se comprueba la actualización?</summary><p>Se buscan marcas del grupo en los días de clase transcurridos de esta semana. Las fechas futuras y las celdas vacías no cuentan. Tener marcas del grupo no garantiza que todos los alumnos tengan registro.</p></details></section>`}

function dashboardSection(key,html){if(!html)return '';const match=html.match(/<h2[^>]*>([\s\S]*?)<\/h2>/);if(!match)return html;let closed=false;try{closed=localStorage.getItem('profeflow-dashboard-'+key)==='closed'}catch{}const body=html.replace(match[0],'').replace('card compact','dashboard-inner');return `<section class="card compact dashboard-section"><div class="dashboard-section-heading"><h2>${match[1]}</h2><button type="button" data-dashboard-toggle="${key}" aria-controls="dashboard-body-${key}" aria-expanded="${!closed}">${closed?'Mostrar':'Minimizar'} <span aria-hidden="true">${closed?'＋':'−'}</span></button></div><div id="dashboard-body-${key}" ${closed?'hidden':''}>${body}</div></section>`}
function bindDashboardSections(){bindAll('[data-dashboard-toggle]',b=>{const key=b.dataset.dashboardToggle,body=$('dashboard-body-'+key),closed=!body.hidden;body.hidden=closed;b.setAttribute('aria-expanded',String(!closed));b.innerHTML=(closed?'Mostrar':'Minimizar')+' <span aria-hidden="true">'+(closed?'＋':'−')+'</span>';try{localStorage.setItem('profeflow-dashboard-'+key,closed?'closed':'open')}catch{}})}
function renderHome(){const subs=subjects(),gids=new Set(list('groups').filter(g=>subs.some(s=>s.id===g.subjectId)).map(g=>g.id)),as=list('activities').filter(a=>gids.has(a.groupId));let waiting=0,missing=0,finished=0;const rows=as.map(a=>{const ss=roster(a.groupId),cells=ss.map(s=>Aula.cell(db,a,s.id,ix)),done=cells.filter(c=>c.complete).length;waiting+=cells.filter(c=>c.needsReview).length;missing+=cells.filter(c=>c.status==='missing').length;if(ss.length&&done===ss.length)finished++;const sub=db.subjects.find(s=>s.id===a.subjectId),g=db.groups.find(g=>g.id===a.groupId);return `<tr><td>${groupAbove(g?.name)}${esc(sub?.name)}</td><td>${esc(a.code||'')} ${esc(a.name)}</td><td><span>${done}/${ss.length} resueltos</span><div class="progress"><span style="width:${ss.length?done/ss.length*100:0}%"></span></div></td><td><button data-open-review="${a.id}" data-student="${ss.find(s=>Aula.cell(db,a,s.id,ix).status==='missing'&&!Aula.cell(db,a,s.id,ix).complete)?.id||ss[0]?.id||''}" ${!ss.length?'disabled':''}>Continuar</button></td></tr>`});
$('content').innerHTML=`${academicCard()}<div class="dashboard-overview"><section class="overview-priority" aria-label="Pendientes de atención"><div class="overview-heading"><span>Tu día docente</span><h2>Por atender</h2></div><div class="overview-priority-grid">${[[waiting,'Entregas por revisar','review','blue','M8 4h8l3 3v13H5V4h3m0 5h8m-8 4h8m-8 4h5'],[justificationPending().length,'Justificaciones pendientes','justifications','violet','M8 3h8v3h4v15H4V6h4m0-3v5h8V3m-8 11 3 3 5-6'],[dashboardAttendanceLists().filter(r=>r.status!=='current').length,'Listas por comprobar','attendance','amber','M4 5h16v16H4V5m3-3v6m10-6v6M4 10h16m-9 4v3m0 2v1']].map(([n,label,target,tone,path])=>`<button class="overview-metric overview-${tone}" data-overview="${target}"><span class="overview-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${path}"/></svg></span><span class="overview-metric-value">${n}</span><span class="overview-metric-label">${label}</span><span class="overview-arrow" aria-hidden="true">↗</span></button>`).join('')}</div></section><section class="overview-summary" aria-label="Resumen del semestre"><div class="overview-heading"><span>Semestre actual</span><h2>Resumen académico</h2></div><div class="overview-summary-grid">${[[subs.length,'Materias activas'],[gids.size,'Grupos'],[list('students').filter(s=>gids.has(s.groupId)).length,'Alumnos'],[as.length-finished,'Actividades pendientes'],[finished,'Actividades terminadas'],[missing,'Sin entregar']].map(([n,label])=>`<div class="overview-summary-item"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div></section></div><div class="toolbar">${button('Continuar revisión','continue',true)}${button('Crear actividad','activity')}${button('Registrar justificante','newJustification')}</div>${dashboardSection('schedule',scheduleDashboard())}${dashboardSection('attendance',attendanceListsDashboard())}${dashboardSection('empty-groups',emptyGroupsDashboard())}${dashboardSection('justifications',justificationDashboard())}${dashboardSection('progress',`<div class="card compact"><h2>Progreso por actividad</h2>${help('¿Qué cuenta como resuelto?','Una entrega está resuelta cuando tiene revisión vigente o un estado final como No válida o No entregó. Sin entregar sigue pendiente hasta que decidas cerrar esa entrega.')}<div class="table-scroll"><table><thead><tr><th>Materia</th><th>Actividad</th><th>Progreso</th><th></th></tr></thead><tbody>${rows.join('')||'<tr><td colspan="4">Crea tus materias, grupos y actividades en Organización.</td></tr>'}</tbody></table></div></div>`)}`;bindAll('[data-overview]',b=>{const target=b.dataset.overview;if(target==='review'){navigate('review');return}if(target==='justifications'){navigate('justifications');return}const body=$('dashboard-body-attendance');if(body?.hidden)document.querySelector('[data-dashboard-toggle="attendance"]')?.click();$('attendanceListsDashboard')?.scrollIntoView?.({behavior:'smooth',block:'start'})});bindSchedule();bindDashboardSections();bindJustificationControls();bindAll('[data-attendance-update]',b=>{const target=db.groups.find(g=>g.id===b.dataset.attendanceUpdate);if(!target)return;subject=target.subjectId;group=target.id;platformAttendanceImport()})}
function continueReview(){const last=db.lastReview,a=last&&list('activities').find(a=>a.id===last.activityId&&Aula.semesterOf(db,a.subjectId)===db.activeSemesterId);const candidates=a?[a,...list('activities').filter(x=>x.id!==a.id&&Aula.semesterOf(db,x.subjectId)===db.activeSemesterId)]:list('activities').filter(x=>Aula.semesterOf(db,x.subjectId)===db.activeSemesterId);for(const a of candidates){const ss=roster(a.groupId),s=ss.find(s=>Aula.cell(db,a,s.id,ix).needsReview)||ss.find(s=>!Aula.cell(db,a,s.id,ix).complete);if(s){openReview(a.id,s.id);return}}toast('No quedan entregas pendientes en este semestre.')}
function simpleStateOptions(selected=''){return options([{id:'missing',name:'Sin entregar'},{id:'pending',name:'Pendiente de revisar'},{id:'reviewed',name:'Revisada'}],selected,'Todos')}
function matchesSimpleState(cell,filter){if(!filter)return true;if(filter==='pending')return !cell.complete;if(filter==='reviewed')return cell.complete;return cell.status==='missing'||cell.status==='not-delivered'||cell.review?.source==='moodle-zero'}
function renderGrades(){if(!group){$('content').innerHTML='<div class="empty">Crea y selecciona una materia, grupo y parcial.</div>';return}const as=activities(),e=ev();$('content').innerHTML=`<div class="student-filter-bar">${studentSearchControl('bookSearch')}${studentSortControl('bookSort')}<div class="student-filter-field"><label for="bookState">Estado</label><select id="bookState">${simpleStateOptions()}</select></div></div><div class="toolbar">${button('Importar calificaciones','gradesImport')}${button('Exportar Excel','export')}</div><p class="context-note">Los porcentajes y parciales se configuran en Organización → Evaluación de la materia.</p>${help('¿Cómo funciona la ponderación?','Cada categoría usa su porcentaje y cada actividad su peso relativo. Los pendientes cuentan provisionalmente como cero; la nota final del parcial aparece cuando todas las categorías con peso están completas. No entregó (cerrada) y No válida cuentan como cero. Un estado Excluir no cuenta en el promedio.')}<div id="bookTable"></div>`;
function table(){const q=Aula.norm($('bookSearch').value),state=$('bookState').value,ss=roster().filter(s=>(matchesStudentSearch(s,q))&&(!state||as.some(a=>matchesSimpleState(Aula.cell(db,a,s.id,ix),state))));$('bookTable').innerHTML=`<div class="table-scroll gradebook"><table><thead><tr><th>Alumno / ID</th>${as.map(a=>`<th title="${esc(a.name)}">${esc(a.code||a.name)}<small>${esc(a.name)} · peso ${a.weight}</small></th>`).join('')}${e.categories.map(c=>`<th>${esc(c.name)}<small>${c.percent} %</small></th>`).join('')}<th>Parcial<small>Base ${e.maxScale}</small></th><th>Semestre<small>Acumulado / final</small></th></tr></thead><tbody>${ss.map(s=>{const summary=Aula.summary(db,s.id,period,ix),semester=Aula.semesterSummary(db,s.id,ix);return `<tr><th><button class="text-button" data-profile="${s.id}">${esc(s.name)}</button><small>${esc(s.number)}</small></th>${as.map(a=>{const c=Aula.cell(db,a,s.id,ix);return `<td><button class="grade-cell" data-open-review="${a.id}" data-student="${s.id}"><strong>${!c.submission.id&&!c.review?'Sin registro':c.score===null?'Pendiente':scaleScore(c.score,e)}</strong>${stateBadge(c)}</button></td>`}).join('')}${e.categories.map(c=>`<td>${c.kind==='exam'?`<button data-exam-student="${s.id}" data-category="${c.id}">${scaleScore(summary.values[c.id],e)} ✎</button>`:scaleScore(summary.values[c.id],e)}</td>`).join('')}<td><strong>${scaleScore(summary.score,e)}</strong>${!summary.ready?`<small title="${esc(summary.pending.join(', '))}">Provisional: ${scaleScore(summary.provisional,e)}</small>`:''}</td><td>${scaleScore(semester.accumulated,e)} / ${scaleScore(semester.final,e)}</td></tr>`}).join('')||'<tr><td>No hay alumnos para este filtro.</td></tr>'}</tbody></table></div>`;bindAll('[data-exam-student]',b=>examForm(b.dataset.examStudent,b.dataset.category));bindGlobalActions()}$('bookSort').onchange=()=>setStudentSort($('bookSort').value);$('bookSearch').oninput=table;$('bookState').onchange=table;table()}
function buildDraft(){const a=act(),cell=Aula.cell(db,a,student,ix),r=cell.review;draft={signedClassScore:r?.signatureValidation?.classScore??(r?.signatureValidation?.signed==='yes'?r.rawScore:100),signature:r?.signatureValidation?.signed||'',values:r?.source==='checklist'?Object.fromEntries(a.criteria.filter(c=>c.id in r.values).map(c=>[c.id,r.values[c.id]])):{},notes:r?.notes||cell.submission.notes||'',status:cell.submission.status,deliveredAt:cell.submission.deliveredAt||'',waiveLate:!!cell.submission.waiveLate,exceptionReason:cell.submission.exceptionReason||'',manualScore:r&&r.source!=='checklist'&&r.signatureValidation?.signed!=='no'?r.rawScore:null,emailOrigin:cell.submission.status==='missing'||r?.source==='moodle-zero'||cell.submission.channel==='email'||cell.submission.status==='email',emailReceived:cell.submission.channel==='email'||cell.submission.status==='email'?'yes':r?.source==='moodle-zero'?'no':'',emailLateRule:cell.submission.channel==='email'||cell.submission.status==='email'?Aula.clone(cell.submission.emailLateRule||a.lateRule):undefined,channel:cell.submission.channel||'',pendingEmailReview:!!cell.submission.pendingEmailReview};if(a.requiresSignature){draft.emailOrigin=draft.status==='email'||draft.channel==='email';if(draft.status==='missing')draft.status='pending'}draftBaseline=JSON.stringify(draft);criterionIndex=0}
