function renderProfile(sid){const s=db.students.find(x=>x.id===sid);if(!s){profileId=null;renderStudents();return}const g=db.groups.find(x=>x.id===s.groupId),sub=db.subjects.find(x=>x.id===g.subjectId),as=list('activities').filter(a=>a.groupId===g.id),sem=Aula.semesterSummary(db,sid,ix);$('content').innerHTML=`<div class="toolbar"><button id="backStudents">← Alumnos</button><button id="profileEdit">Editar alumno</button></div><div class="card compact">${groupAbove(g.name)}<h2>${esc(s.name)}</h2><p class="muted">ID: ${esc(s.number||'—')} · ${esc(sub.name)}</p><div class="table-scroll"><table><thead><tr><th>Parcial</th>${sub.evaluation.categories.map(c=>`<th>${esc(c.name)}</th>`).join('')}<th>Calificación</th></tr></thead><tbody>${sem.periods.map(({period:p,value:v})=>`<tr><td>${esc(p.name)} · peso ${p.weight}</td>${sub.evaluation.categories.map(c=>`<td>${scaleScore(v.values[c.id],sub.evaluation)}</td>`).join('')}<td>${scaleScore(v.score,sub.evaluation)}${!v.ready?' · Pendiente':''}</td></tr>`).join('')}</tbody></table></div><p>Acumulado de parciales completos: <strong>${scaleScore(sem.accumulated,sub.evaluation)}</strong> · Semestre final: <strong>${scaleScore(sem.final,sub.evaluation)}</strong></p></div><div class="card compact"><h2>Actividades y entregas</h2><table><thead><tr><th>Actividad</th><th>Estado</th><th>Nota</th><th>Entrega</th><th>Observaciones</th></tr></thead><tbody>${as.map(a=>{const c=Aula.cell(db,a,sid,ix);return `<tr><td><button data-open-review="${a.id}" data-student="${sid}">${esc(a.code)} ${esc(a.name)}</button></td><td>${stateBadge(c)}</td><td>${scaleScore(c.score,sub.evaluation)}</td><td>${esc(c.submission.deliveredAt||'—')}${c.penalty.days?' · '+c.penalty.days+' días de atraso':''}</td><td>${esc(c.review?.notes||c.submission.notes||'')}</td></tr>`}).join('')}</tbody></table></div><div class="card compact"><h2>Historial de revisiones</h2>${db.reviews.filter(r=>r.studentId===sid&&!r.trashId).slice().reverse().map(r=>`<details class="history-item"><summary>${esc(r.activityName)} · ${scaleScore(r.score,sub.evaluation)} · ${new Date(r.date).toLocaleString('es-MX')}</summary><p>${esc(r.notes)}</p><p class="muted">Origen: ${esc(r.source)} · Sin penalización: ${scaleScore(r.rawScore,sub.evaluation)}</p><table>${r.criteria?.map(c=>`<tr><td>${esc(c.name)}</td><td>${r.values[c.id]===undefined?'—':Aula.round(r.values[c.id]*c.weight)} / ${c.weight}</td></tr>`).join('')||''}</table><button data-open-review="${r.activityId}" data-student="${sid}">Abrir revisión actual</button></details>`).join('')||'<p class="muted">Sin revisiones todavía.</p>'}<h3>Historial de entregas y excepciones</h3>${db.submissions.filter(x=>x.studentId===sid&&!x.trashId).flatMap(x=>(x.events||[]).map(event=>({activityId:x.activityId,event}))).sort((a,b)=>b.event.date.localeCompare(a.event.date)).map(({activityId,event})=>`<p class="muted">${esc(db.activities.find(a=>a.id===activityId)?.name)} · ${esc(db.settings.statuses.find(s=>s.id===event.status)?.name)} · ${new Date(event.date).toLocaleString('es-MX')}<br>${esc(event.notes||'')} ${event.waiveLate?' · Excepción: '+esc(event.exceptionReason):''}</p>`).join('')||'<p class="muted">Sin cambios de entrega registrados.</p>'}<h3>Historial de exámenes</h3>${db.exams.filter(r=>r.studentId===sid&&!r.trashId).slice().reverse().map(r=>`<p class="muted">${esc(db.periods.find(p=>p.id===r.periodId)?.name)} · ${esc(sub.evaluation.categories.find(c=>c.id===r.categoryId)?.name)}: ${scaleScore(r.score,sub.evaluation)} · ${new Date(r.date).toLocaleString('es-MX')}</p>`).join('')||'<p class="muted">Sin exámenes registrados.</p>'}</div>`;$('backStudents').onclick=()=>{profileId=null;render()};$('profileEdit').onclick=()=>entityForm('students',sid)}
function renderManage(){$('content').innerHTML=`<div class="toolbar">${button('Nueva materia','subject',true)}${button('Nuevo parcial','period')}${button('Nuevo semestre','semester')}${button('Evaluación de la materia','evaluation')}<button id="teachingScheme">Aplicar esquema 70/30 · 25/25/50</button>${button('Estados y opciones','settings')}</div><div class="columns"><div class="card compact"><h2>Materias del semestre</h2><p class="muted">Agrega grupos desde la fila de su materia. Los nombres son libres.</p>${subjects().map(s=>`<div class="management-row"><span><div class="group-above">${groupsForSubject(s.id).map(g=>groupTag(g.name)).join(' ')||'<span class="muted">Sin grupos asignados</span>'}</div><button class="text-button" data-select-subject="${s.id}">${esc(s.name)}</button></span><div><button data-add-group="${s.id}">+ Grupo</button><button data-edit-entity="subjects|${s.id}">Editar</button><button data-duplicate-subject="${s.id}">Duplicar</button><button data-archive="subjects|${s.id}">Archivar</button><button data-trash="subjects|${s.id}">Eliminar</button></div></div>`).join('')||'<p>Crea tu primera materia.</p>'}</div><div class="card compact"><h2>Grupos y sus materias</h2><div class="organization-groups">${groupAssignments().map(g=>`<article class="organization-group"><div class="organization-group-main">${groupAbove(g.name)}<h3>${esc(db.subjects.find(s=>s.id===g.subjectId)?.name)}</h3></div><div class="organization-group-count"><strong>${roster(g.id).length}</strong><span>alumnos</span></div><div class="organization-group-actions"><button class="primary" data-open-group="${g.id}">Abrir grupo <span aria-hidden="true">↗</span></button><button data-edit-entity="groups|${g.id}">Editar / asignar</button><details class="activity-more group-more"><summary>Más acciones</summary><div><button data-copy-group="${g.id}">Copiar a otra materia</button><button data-archive="groups|${g.id}">Archivar</button><button data-trash="groups|${g.id}" class="danger">Eliminar grupo</button></div></details></div></article>`).join('')||'<p class="empty">Agrega un grupo con su nombre real desde la fila de su materia.</p>'}</div><h3>Parciales de ${esc(db.subjects.find(s=>s.id===subject)?.name||'la materia seleccionada')}</h3>${periods().map(p=>`<div class="management-row"><span>${esc(p.name)} · peso ${p.weight}</span><button data-edit-entity="periods|${p.id}">Editar</button></div>`).join('')}</div></div><div class="card compact"><h2>Semestres</h2>${help('¿Cómo reutilizar la configuración?','Duplica un semestre para copiar materias, grupos, parciales, categorías, escalas y actividades sin calificaciones. Puedes incluir los alumnos. Las fechas se vacían para evitar reutilizar límites antiguos. Las plantillas son compartidas entre semestres.')}<table>${db.semesters.map(s=>`<tr><td>${esc(s.name)}${s.id===db.activeSemesterId?' · activo':''}${s.archivedAt?' · archivado':''}</td><td><button data-edit-semester="${s.id}">Editar</button><button data-copy-semester="${s.id}">Duplicar configuración</button><button data-archive-semester="${s.id}">${s.archivedAt?'Desarchivar':'Archivar'}</button></td></tr>`).join('')}</table></div>`;$('teachingScheme').onclick=gradingSchemeForm;bindAll('[data-add-group]',b=>groupForm(null,b.dataset.addGroup));bindAll('[data-select-subject]',b=>{if(!leave())return;subject=b.dataset.selectSubject;render()});bindAll('[data-open-group]',b=>{if(!leave())return;const g=db.groups.find(g=>g.id===b.dataset.openGroup);subject=g.subjectId;group=g.id;view='students';profileId=null;render()});bindAll('[data-copy-group]',b=>copyGroupForm(b.dataset.copyGroup));bindAll('[data-edit-entity]',b=>{const [k,id]=b.dataset.editEntity.split('|');entityForm(k,id)});bindAll('[data-duplicate-subject]',b=>duplicateSubjectForm(b.dataset.duplicateSubject));bindAll('[data-edit-semester]',b=>semesterForm(b.dataset.editSemester));bindAll('[data-copy-semester]',b=>copySemesterForm(b.dataset.copySemester));bindAll('[data-archive-semester]',async b=>{try{await mutate(d=>{const s=d.semesters.find(x=>x.id===b.dataset.archiveSemester);if(s.archivedAt)delete s.archivedAt;else s.archivedAt=new Date().toISOString()});render()}catch(e){toast(e.message)}});bindArchiveTrash()}
function bindArchiveTrash(){document.querySelectorAll('[data-trash]').forEach(b=>b.classList.toggle('danger',true));document.querySelectorAll('[data-archive]').forEach(b=>b.classList.toggle('archive-action',true));bindAll('[data-archive]',async b=>{const [kind,id]=b.dataset.archive.split('|');try{await mutate(d=>d[kind].find(x=>x.id===id).archivedAt=new Date().toISOString(),'Archivado. Disponible en Datos.');render()}catch(e){toast(e.message)}});bindAll('[data-trash]',async b=>{const [kind,id]=b.dataset.trash.split('|'),entity=db[kind].find(x=>x.id===id);if(!confirm(`¿Eliminar “${entity.name}” y sus datos relacionados? Podrás restaurarlos desde Datos.`))return;try{await mutate(d=>Aula.trashItem(d,kind,id),'Eliminado. Puedes restaurarlo desde Datos.');render()}catch(e){toast(e.message)}})}
function initShell(){let collapsed=false;try{collapsed=localStorage.getItem('aula-sidebar-collapsed')==='true'}catch(e){}function sidebar(){document.body.classList.toggle('sidebar-collapsed',collapsed);$('sidebarToggle').innerHTML='<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="'+(collapsed?'m9 6 6 6-6 6':'m15 6-6 6 6 6')+'"/></svg>';$('sidebarToggle').setAttribute('aria-expanded',String(!collapsed));$('sidebarToggle').setAttribute('aria-label',collapsed?'Expandir menú':'Contraer menú')}$('sidebarToggle').onclick=()=>{collapsed=!collapsed;sidebar();try{localStorage.setItem('aula-sidebar-collapsed',String(collapsed))}catch(e){}};sidebar();bindAll('[data-view]',b=>navigate(b.dataset.view));$('closeModal').onclick=closeModal;$('cancel').onclick=closeModal;$('modalForm').addEventListener('invalid',e=>{e.preventDefault();const f=e.target,label=f.getAttribute('aria-label')||document.querySelector(`label[for="${f.id}"]`)?.textContent||'Campo obligatorio';modalError(label+': '+f.validationMessage);f.scrollIntoView({block:'center'})},true);$('semesterSelect').onchange=async e=>{if(!leave()){render();return}try{await mutate(d=>d.activeSemesterId=e.target.value,'');subject='';group='';period='';activity='';student='';profileId=null;render()}catch(error){toast(error.message)}};
$('globalSearch').oninput=()=>{const q=Aula.norm($('globalSearch').value);$('globalResults').hidden=!q;if(!q)return;const matches=list('students').filter(s=>matchesStudentSearch(s,q)).slice(0,30);$('globalResults').innerHTML=matches.map(s=>{const g=db.groups.find(g=>g.id===s.groupId),sub=db.subjects.find(x=>x.id===g.subjectId),as=list('activities').filter(a=>a.groupId===g.id),pending=as.filter(a=>!Aula.cell(db,a,s.id,ix).complete).length,semester=Aula.semesterSummary(db,s.id,ix);return `<button data-search-profile="${s.id}">${groupAbove(g.name)}<strong>${esc(s.name)} · ${esc(s.number)}</strong><small>${esc(sub.name)} · ${esc(db.semesters.find(x=>x.id===sub.semesterId)?.name)} · ${as.length} actividades · ${pending} pendientes · Acumulado ${scaleScore(semester.accumulated,sub.evaluation)}</small></button>`}).join('')||'<p>Sin coincidencias</p>';bindAll('[data-search-profile]',b=>{if(!leave())return;const s=db.students.find(x=>x.id===b.dataset.searchProfile),g=db.groups.find(x=>x.id===s.groupId);subject=g.subjectId;group=g.id;db.activeSemesterId=Aula.semesterOf(db,subject);profileId=s.id;view='students';$('globalResults').hidden=true;$('globalSearch').value='';render()})};document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('globalResults').hidden=true});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('globalResults').hidden=true;if(view!=='review'||!draft||$('modal').open||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();commitReview(true);return}if(e.ctrlKey||e.altKey||e.metaKey)return;const a=act();if(!a.criteria.length)return;if(/^[1-4]$/.test(e.key)){const level=ev().responseScale[+e.key-1];if(level){e.preventDefault();setCriterion(a.criteria[criterionIndex].id,level.ratio,criterionIndex)}}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();criterionIndex=Math.max(0,Math.min(a.criteria.length-1,criterionIndex+(e.key==='ArrowDown'?1:-1)));highlightCriterion();document.querySelector(`[data-row-index="${criterionIndex}"]`)?.focus()}});window.addEventListener('beforeunload',e=>{if(dirty()||$('saveStatus').textContent==='Guardando…'){e.preventDefault();e.returnValue=''}})}
async function boot(){try{const loaded=await AulaStorage.load();db=loaded.data;restoreContext();initShell();$('saveStatus').textContent='Guardado · '+loaded.mode;render();if(loaded.idsNormalized)toast('Formato aplicado y guardado en todos los IDs actuales.');if(loaded.migrated)toast('Datos anteriores migrados. Se conserva el original en localStorage.');if(loaded.mode==='localStorage'){$('storageError').hidden=false;$('storageError').textContent='IndexedDB no disponible. Se usa localStorage como respaldo; descarga copias periódicas.'}}catch(error){$('content').innerHTML='<div class="warning"><h2>No se pudieron abrir los datos</h2><p>'+esc(error.message)+'</p><p>No se han borrado ni sustituido tus datos anteriores.</p><button id="recoverOld">Descargar datos anteriores</button></div>';$('recoverOld').onclick=()=>{for(const key of ['aula-docente-v2','aula-revision-v1']){const raw=localStorage.getItem(key);if(raw)download(raw,key+'.json')}}}}


async function closeNoEmail(){const a=act(),s=db.students.find(s=>s.id===student);try{await mutate(d=>{const current=Aula.cell(d,a,s.id,Aula.index(d));if(current.review?.source==='moodle-zero'&&current.score===0)return;const r=Aula.saveReview(d,a,s,{},'Sin entregar en Moodle.',{status:'reviewed',deliveredAt:'',waiveLate:false,exceptionReason:'',channel:'none',source:'moodle',emailLateRule:undefined},0);r.source='moodle-zero'});draft=null;render()}catch(e){$('reviewError').textContent=e.message;$('reviewError').hidden=false}}
